#!/usr/bin/env bash
# need.sh: missing-tool guard for Makefile recipes (spec 026, FR-010, research R6).
#
# Usage: hack/need.sh <tool>...
#
# Exits 0 when every tool is on PATH. Otherwise, for each missing tool, prints
# which dev container profile installs it and exits 127 ("command not found").
#
# Lookup: .devcontainer/tool-index.tsv (generated by hack/gen-devcontainers.py)
# maps a dependency name to its owning profiles and declaring folder. Index rows
# use dependency names, so the binaries npm and npx are mapped to "node" below.
# When the index is absent, or has no row for the tool, only the plain
# "not installed" line is printed.
set -euo pipefail

if [ "$#" -eq 0 ]; then
	echo "usage: hack/need.sh <tool>..." >&2
	exit 2
fi

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
INDEX="$ROOT/.devcontainer/tool-index.tsv"

# Binary name -> dependency name used in tool-index.tsv.
# npm and npx are both provided by the node dependency.
dep_name() {
	case "$1" in
		npm|npx) echo "node" ;;
		*) echo "$1" ;;
	esac
}

# Print the index row for dependency $1 as "name<TAB>profiles<TAB>dir", or nothing.
lookup() {
	local want="$1" name="" profiles="" dir=""
	[ -f "$INDEX" ] || return 0
	while IFS=$'\t' read -r name profiles dir || [ -n "$name" ]; do
		if [ "$name" = "$want" ]; then
			printf '%s\t%s\t%s\n' "$name" "$profiles" "$dir"
			return 0
		fi
	done < "$INDEX"
	return 0
}

missing=0
for tool in "$@"; do
	if command -v "$tool" >/dev/null 2>&1; then
		continue
	fi
	missing=1
	row="$(lookup "$(dep_name "$tool")")"
	if [ -z "$row" ]; then
		echo "need: $tool is not installed." >&2
		continue
	fi
	IFS=$'\t' read -r _ profiles dir <<< "$row"
	# At most the first two profile ids, smallest profile first.
	p1="" p2=""
	IFS=',' read -r p1 p2 _ <<< "$profiles"
	if [ -n "$p2" ]; then
		open="\"$p1\" or \"$p2\""
	else
		open="\"$p1\""
	fi
	case "$dir" in
		baseline|extras:*) source_note=".devcontainer/profiles.toml" ;;
		*) source_note="$dir/system-deps.toml" ;;
	esac
	echo "need: $tool is not installed in this dev container." >&2
	echo "      Open the $open profile (declared in $source_note)." >&2
done

if [ "$missing" -ne 0 ]; then
	exit 127
fi
exit 0
